/**
 * The README leaderboard, generated from results/results.json, so the README
 * and the data can never disagree.
 */

import { readFileSync } from 'node:fs';
import { repoPath } from './config.js';

export const START =
  '<!-- leaderboard:start (generated by `npm run geb -- report`; do not edit) -->';
export const END = '<!-- leaderboard:end -->';

const percent = (value) =>
  value === null || value === undefined ? '–' : `${Math.round(value * 100)}%`;
const interval = (ci) => (ci ? `${percent(ci[0])}–${percent(ci[1])}` : '–');
const number = (value, digits = 1) =>
  value === null || value === undefined ? '–' : value.toFixed(digits);
const thousands = (value) =>
  value === null || value === undefined ? '–' : `${Math.round(value / 1000)}k`;

/** A Markdown table cell: pipes escaped and lines joined, so a label cannot break the table. */
const cell = (value) =>
  String(value)
    .replaceAll('|', '\\|')
    .replace(/\s*\n\s*/g, ' ');

/** A count of trials, as "2 of 12". */
const ofTrials = (measure) =>
  measure ? `${measure.followed} of ${measure.trials}` : '–';

/** The results table: how often each agent was right, and how honest. */
function resultsTable(runs) {
  const rows = runs.map((run) => {
    const result = run.public;
    return `| ${cell(run.label)} | **${percent(result.accuracy)}** (${interval(result.accuracy_ci95)}) | ${run.heldout ? percent(run.heldout.accuracy) : '–'} | ${percent(result.by_difficulty?.hard)} | ${ofTrials(result.followed_injection)} | ${percent(result.honest_about_faults)} | ${percent(result.false_absence)} | ${percent(result.fabrication)} |`;
  });
  return [
    '| Harness + model | Accuracy (95% CI) | Held-out | Hard questions | Followed a planted instruction | Faults reported | Said "none" wrongly | Invented a value |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
    ...rows,
  ].join('\n');
}

/** The tool-use table: how each agent worked, what it cost, and how it ran. */
function toolUseTable(runs) {
  const rows = runs.map((run) => {
    const result = run.public;
    return `| ${cell(run.label)} | ${number(result.tool_calls_mean)} | ${percent(result.off_limits_trials)} | ${percent(result.replay_miss_trials)} | ${percent(result.accuracy_without_misses)} | ${percent(result.nudged_trials)} | ${result.second_attempts ?? '–'} | ${number(result.latency_median_s)} s | ${thousands(result.tokens_mean)} | ${(run.provenance.bench_versions ?? [run.provenance.bench_version]).join(', ')} |`;
  });
  return [
    '| Harness + model | Tool calls | Off-limits tools | Hit an unrecorded request | Accuracy without those | Asked again for an answer | Second attempts | Median time | Tokens | Bench version |',
    '| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |',
    ...rows,
  ].join('\n');
}

/**
 * The line every verified run shares: snapshot, God's Eye View commit,
 * question count, trials and prompt. Runs that differ cannot share a table.
 */
function sharedSetup(runs) {
  const setups = new Set(
    runs.map(
      (run) =>
        `Snapshot \`${run.provenance.snapshot.id}\` · God's Eye View \`${run.provenance.gev.commit.slice(0, 7)}\` (v${run.provenance.gev.version}) · ${run.public.questions} public questions · ${run.trials_per_question} trials each · prompt v${run.provenance.prompt_version}`,
    ),
  );
  if (setups.size > 1)
    throw new Error(
      `Verified runs differ in setup and cannot share one table: ${[...setups].join(' / ')}`,
    );
  return [...setups][0];
}

/** The generated leaderboard section, between its markers. */
export function leaderboardSection(results) {
  // The scripted reference agent proves every question is answerable; it is
  // a check on the benchmark, not a contestant.
  const isReference = (run) => run.harness?.adapter === 'reference';
  const reference = results.runs.find(isReference);
  const verified = results.runs.filter(
    (run) => run.status === 'verified' && !isReference(run),
  );
  const community = results.runs.filter((run) => run.status === 'community');
  const runTables = (runs) =>
    runs.length
      ? [
          resultsTable(runs),
          '',
          '<details><summary>Tool use, tokens and run details</summary>',
          '',
          toolUseTable(runs),
          '',
          '</details>',
        ].join('\n')
      : '_None yet._';
  return [
    START,
    '',
    '### Verified runs',
    '',
    verified.length ? sharedSetup(verified) : 'No verified runs yet.',
    '',
    runTables(verified),
    ...(reference
      ? [
          '',
          `The scripted reference agent (no model) scores ${percent(reference.public.accuracy)} on the public questions and ${reference.heldout ? percent(reference.heldout.accuracy) : '–'} on the held-out ones through the same tools, so every question is answerable.`,
        ]
      : []),
    '',
    '### Community-reported runs',
    '',
    'Submitted by pull request and rescored from their logs, but not reproduced by the maintainer.',
    '',
    runTables(community),
    '',
    END,
  ].join('\n');
}

/** The README with its leaderboard section regenerated, formatted as the repo formats Markdown. */
export async function renderReadme(readme, results) {
  const start = readme.indexOf(START);
  const end = readme.indexOf(END);
  if (start < 0 || end < start)
    throw new Error('README has no leaderboard markers');
  const next =
    readme.slice(0, start) +
    leaderboardSection(results) +
    readme.slice(end + END.length);
  // Prettier is a development tool: only `geb report` needs it, so the
  // rest of the command line runs without development packages.
  const { format } = await import('prettier');
  return format(next, {
    parser: 'markdown',
    ...readJson(repoPath('.prettierrc.json')),
  });
}

/** Read a JSON file. */
export function readJson(file) {
  return JSON.parse(readFileSync(file, 'utf8'));
}
